void Scoreboard::drawscore(int n) {
if (n > 0) { score[numdigits]->erase();
}
numdigits = 0; if (n == 0) { delete score[numdigits]; score[numdigits] = new Displayable(digits[0]); score[numdigits]->move(Point((700-numdigits*18),40)); score[numdigits]->draw(); numdigits++;
}
while (n) {
int rem = n % 10;
delete score[numdigits]; score[numdigits] = new Displayable(digits[rem]); score[numdigits]->move(Point((700-numdigits*18),40)); score[numdigits]->draw(); n /= 10; numdigits++;
}
}

