public class SingletonExam
{
private static int counter = 0; private static class Singleton
{
private static SingletonExam INSTANCE = new SingletonExam();
}
public static SingletonExam getInstance()
{
counter++; return Singleton.INSTANCE;
}
private SingletonExam()
{
counter++;
}
public void increaseCounter()
{
counter++;
}
public int getCounter()
{
return counter;
}
}
public class ExamThreeMain
{
public static void main(String[] args)
{
SingletonExam se = SingletonExam.getInstance(); se.increaseCounter(); se.increaseCounter(); SingletonExam.getInstance().increaseCounter(); SingletonExam.getInstance().increaseCounter(); System.out.println (SingletonExam.getInstance().getCounter());
}
}
